def resolve(path, cwd, links):
    if links is None:
        links = {}

    # Determine starting path
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    # Split into components, filtering empty ones and '.'
    components = [c for c in remaining.split('/') if c and c != '.']

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        comp = components[i]

        if comp == '..':
            # Move to parent
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
            i += 1
        else:
            # Append component
            if current == '/':
                new_path = '/' + comp
            else:
                new_path = current + '/' + comp

            # Check if this is a symlink
            if new_path in links:
                link_count += 1
                if link_count > max_links:
                    return None

                target = links[new_path]

                # Get remaining components after this one
                remaining_components = components[i+1:]

                # Parse the target
                if target.startswith('/'):
                    current = '/'
                    target_components = [c for c in target[1:].split('/') if c and c != '.']
                else:
                    # Relative to directory containing the link
                    if new_path == '/':
                        current = '/'
                    else:
                        current = new_path.rsplit('/', 1)[0]
                        if not current:
                            current = '/'
                    target_components = [c for c in target.split('/') if c and c != '.']

                # Replace components: target components + remaining components
                components = target_components + remaining_components
                i = 0
            else:
                current = new_path
                i += 1

    # Remove trailing slash except for root
    if current == '/':
        return '/'
    else:
        return current

